package dev.overalls.mila.nativeui
import org.junit.Assert.*
import org.junit.Test
private open class ControlsAdapter: MilaFfiAdapter { override suspend fun call(r:MilaFfiRequest)=MilaFfiResult.Failure(MilaFfiError.Unavailable); override fun machineCommandKind(v:String)=if(v=="start") Result.success(MilaMachineCommand.Start) else Result.failure(Exception()); override fun terminalAttach(f:Long,c:Int,r:Int,w:Boolean)=Result.success(Unit); override fun terminalResize(c:Int,r:Int,w:Boolean)=Result.success(Unit) }
class MilaMachineControlsTest { @Test fun terminalInputBoundUsesUtf8Bytes(){ assertTrue(boundedTerminalInput("é".repeat(2048))); assertFalse(boundedTerminalInput("é".repeat(2049))) }
 @Test fun reconnectResumesFromReceivedCursor(){ val from = mutableListOf<Long>(); val a = object: ControlsAdapter() { override fun terminalAttach(f:Long,c:Int,r:Int,w:Boolean): Result<Unit> { from += f; return Result.success(Unit) } }; val t=MilaTerminalController(a); assertTrue(t.attach(false)); assertTrue(t.receive("hello".toByteArray())); t.close(); assertTrue(t.reconnect(false)); assertEquals(listOf(0L, 5L), from); assertEquals(5L, t.state.cursor) }
 @Test fun actionsUseClosedCatalog(){ val c=MilaMachineActionController(ControlsAdapter()); c.select("start"); assertEquals(MilaMachineActionState.Selected(MilaMachineCommand.Start),c.state); c.select("bogus"); assertTrue(c.state is MilaMachineActionState.Rejected) } @Test fun terminalBoundsAndPhases(){ val t=MilaTerminalController(ControlsAdapter()); assertTrue(t.attach(false)); assertEquals(MilaTerminalPhase.ReadOnly,t.state.phase); assertTrue(t.receive("ok\u001b[31m\n".toByteArray())); assertTrue(t.renderer.text().contains("ok")); assertFalse(t.resize(0,24)); assertTrue(t.resize(100,30)); assertEquals(100,t.state.columns) } @Test fun rendererFiltersAndBoundsHistory(){ val r=MilaTerminalRenderer(); r.append("hello\u0007\nworld".toByteArray()); assertEquals("hello\nworld",r.text()); repeat(205){r.append("x\n".toByteArray())}; assertTrue(r.text().lines().size<=200) } @Test fun reconnectReopensClosedTerminal(){ val t=MilaTerminalController(ControlsAdapter()); t.close(); assertTrue(t.reconnect(false)); assertEquals(MilaTerminalPhase.ReadOnly,t.state.phase); assertFalse(t.input(3)); assertTrue(t.resize(120,40)); assertEquals(120,t.state.columns); assertEquals(40,t.state.rows) }
 @Test fun pollReadsOnlyWhenAttachedAndHandlesSplitAnsi(){ var reads = 0; val t = MilaTerminalController(ControlsAdapter(), MilaPtySource { max -> reads++; assertEquals(MilaTerminalController.MAX_READ_BYTES, max); "ok\u001b[".toByteArray() }); assertFalse(t.pollOutput()); assertTrue(t.attach(false)); assertTrue(t.pollOutput()); assertEquals("ok", t.renderer.text()); val split = MilaTerminalRenderer(); split.append("a\u001b[3".toByteArray()); split.append("1mb\n".toByteArray()); assertEquals("ab", split.text()); assertEquals(2, reads) }
 @Test fun pollRejectsOversizedHostRead(){ val t = MilaTerminalController(ControlsAdapter(), MilaPtySource { ByteArray(MilaTerminalController.MAX_READ_BYTES + 1) }); assertTrue(t.attach(false)); assertFalse(t.pollOutput()); assertEquals("", t.renderer.text()) }
 @Test fun cleanPtyEofClosesTerminalAndRejectsInput(){ val t=MilaTerminalController(ControlsAdapter()); assertTrue(t.attach(true)); assertTrue(t.receive(byteArrayOf())); assertEquals(MilaTerminalPhase.Closed,t.state.phase); assertFalse(t.input(1)) }
 @Test fun inputRejectsNegativeAndOversizedPayloads(){ val t = MilaTerminalController(ControlsAdapter()); assertTrue(t.attach(true)); assertFalse(t.input(-1)); assertFalse(t.input(MilaTerminalController.MAX_READ_BYTES + 1)); assertTrue(t.input(MilaTerminalController.MAX_READ_BYTES)) }
}
